package com.rikkeibank.notification.service; import java.time.Instant; import java.util.concurrent.ConcurrentLinkedDeque; import org.slf4j.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux;
@Service public class NotificationEventStore{private static final Logger log=LoggerFactory.getLogger(NotificationEventStore.class);private final ConcurrentLinkedDeque<ReceivedEvent> events=new ConcurrentLinkedDeque<>();@KafkaListener(topics={"${app.kafka.transfer-completed-topic:transfer.completed}","${app.kafka.transfer-failed-topic:transfer.failed}"},groupId="${spring.kafka.consumer.group-id:notification-service}") public void consume(String payload){ReceivedEvent e=new ReceivedEvent(Instant.now(),payload);events.addFirst(e);while(events.size()>100)events.pollLast();log.info("Notification event received: {}",payload);}@SuppressWarnings("unchecked") public Flux<ReceivedEvent> stream(){return Flux.fromIterable(events);}public record ReceivedEvent(Instant receivedAt,String payload){}}
